using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using V15Voice;
public static class ExternalCloneTests {
 static int count;static string root,ai,output;static List<string> activity=new List<string>();
 static void Check(bool x,string name){if(!x)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}
 static void Scenario(string name){foreach(string f in new[]{"starts.txt","hung","crashed"})if(File.Exists(Path.Combine(ai,f)))File.Delete(Path.Combine(ai,f));File.WriteAllText(Path.Combine(ai,"scenario.txt"),name);if(File.Exists(output))File.Delete(output);activity.Clear();}
 static string[] Starts(){return File.ReadAllLines(Path.Combine(ai,"starts.txt"));}
 static KokoroEngine Engine(string device="auto"){var e=new KokoroEngine{Root=root,Kind=EngineKind.Qwen,ModelFolder="qwen_base",VoiceName="ADAM",ReferencePath=Path.Combine(ai,"reference.wav"),DeviceMode=device,RenderContext="sample.srt · khối 10/21",ActivityChanged=s=>activity.Add(s)};var c=new List<Cue>{new Cue{Id=1,Start=0,End=1,Text="First sentence."}};var o=new RenderOptions{ReportContext=new VoiceReportContext{SourceCues=c}};e.RunReport=new VoiceRenderReport(c,e,o,Path.Combine(root,"diagnostic.wav"));e.RunReport.Step("TTS","Fixture worker request");e.RunReport.BeginUnit(c[0].Text);return e;}
 static Exception Error(Action f){try{f();}catch(Exception e){return e;}throw new Exception("Expected failure");}
 public static void Main(string[] args){root=Path.GetFullPath(args[0]);ai=Path.Combine(root,"ai");output=Path.Combine(root,"out.wav");File.WriteAllText(Path.Combine(ai,"allpids.txt"),"");
  Scenario("success");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){var a=x.Generate("First sentence.",1,output);x.Generate("Next sentence.",1,output);Check(a.Duration==.4&&Starts().Length==1,"Multiple cues reuse one healthy model worker");Check(activity.Any(s=>s.Contains("Sinh fixture"))&&activity.All(s=>s.Contains("khối 10/21")),"Unicode STATUS protocol is consumed as activity with cue context, not mistaken for READY/OK");}
  Scenario("hangonce");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,350)){x.Generate("First sentence.",1,output);Check(Starts().Length==2&&Starts()[1].StartsWith("auto 1 "),"Timeout kills old worker, changes retry seed offset and starts exactly one fresh worker");Check(activity.Any(s=>s.Contains("khởi động lại")),"Recovery attempt is visible to user");Check(e.RunReport.ProcessDiagnostics.Count==1&&e.RunReport.ProcessDiagnostics[0].Disposition.Contains("Sẽ thử lại"),"Recovered worker timeout is retained in the report journal");}
  Scenario("hangalways");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,300)){var clock=Stopwatch.StartNew();var error=Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==2&&clock.Elapsed.TotalSeconds<4,"Permanent hang is bounded at one process restart");Check(error.Message.Contains("sample.srt")&&error.Message.Contains("khối 10/21")&&error.Message.Contains("NVIDIA CUDA")&&!File.Exists(output),"Terminal timeout reports file/cue/actual device and produces no WAV");}
  Scenario("statushang");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,300)){var clock=Stopwatch.StartNew();Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==2&&clock.Elapsed.TotalSeconds<4,"Frequent progress messages cannot extend absolute generation deadline");}
  Scenario("crashonce");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){x.Generate("First sentence.",1,output);Check(Starts().Length==2,"Unexpected child exit restarts once and completes current cue");Check(e.RunReport.ProcessDiagnostics.Count==1&&e.RunReport.ProcessDiagnostics[0].ExitCode==9,"Actual crashed worker records exit 9 before successful restart");}
  Scenario("startupoom");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){x.Generate("First sentence.",1,output);Check(Starts().Length==2&&Starts()[1].StartsWith("cpu ")&&e.DeviceInfo.Contains("CPU dự phòng"),"Fast startup error is drained before exit and triggers Auto CPU recovery");}
  Scenario("startuphangalways");using(var e=Engine())using(var x=new ExternalSpeech(e,300,600)){Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==2,"Startup/model-loading hang has its own bounded deadline and one fresh retry");}
  Scenario("oom");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){x.Generate("First sentence.",1,output);x.Generate("Next sentence.",1,output);Check(Starts().Length==2&&Starts()[1].StartsWith("cpu "),"Runtime CUDA error uses one fresh CPU worker; next cue stays on that worker");Check(e.RunReport.ProcessDiagnostics.Count==1&&e.RunReport.ProcessDiagnostics[0].Exception.Contains("GPU_FALLBACK"),"Actual CUDA fallback retains original worker protocol error");}
  Scenario("oom");using(var e=Engine("gpu"))using(var x=new ExternalSpeech(e,2000,600)){var error=Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==1&&error.Message.Contains("GPU_FALLBACK"),"Required GPU reports CUDA error without silently switching to CPU");}
  Scenario("invalid");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){var error=Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==1&&error.Message.Contains("SYNTH_INVALID"),"Exhausted three-attempt worker error does not multiply into further retries");File.WriteAllText(Path.Combine(ai,"scenario.txt"),"success");x.Generate("Next file.",1,output);Check(Starts().Length==2,"Next file starts a fresh worker after invalid-audio failure");}
  Scenario("unrelated");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==1,"Invalid reference/model errors are not retried as a timeout or CUDA failure");}
  Scenario("malformed");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){Error(()=>x.Generate("First sentence.",1,output));Check(Starts().Length==1&&!File.Exists(output),"Malformed protocol fails safely without false success");}
  Scenario("badwav");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,600)){var error=Error(()=>x.Generate("First sentence.",1,output));Check(error.Message.Contains("WAV"),"Worker OK cannot bypass parent WAV validation");}
  Scenario("cancel");using(var e=Engine())using(var x=new ExternalSpeech(e,2000,2000)){var task=Task.Run(()=>Error(()=>x.Generate("First sentence.",1,output)));Thread.Sleep(200);e.Cancelled=true;x.Cancel();var error=task.Result;Check(error is OperationCanceledException&&Starts().Length==1,"Cancel kills the active child and never starts a recovery worker");}
  Scenario("cue10");string first=Path.Combine(root,"first.srt"),second=Path.Combine(root,"second.srt");var cues=Enumerable.Range(0,21).Select(i=>new Cue{Id=i+1,Start=i,End=i+1,Text="Complete narration sentence."}).ToList();File.WriteAllText(first,Scripts.ToSrt(cues));File.WriteAllText(second,Scripts.ToSrt(cues.Take(2).ToList()));var jobs=new List<BatchJob>{BatchJob.Load(first),BatchJob.Load(second)};
  using(var e=Engine()){var opts=new RenderOptions{Breathing=BreathMode.None,SlowShort=false};BatchRunner.Run(jobs,false,()=>false,(j,f,p)=>Renderer.Render(j.Cues,e,opts,f,p),(n,m)=>{});Check(jobs[0].State==JobState.Failed&&jobs[0].Error.Contains("khối 10/21")&&!File.Exists(Path.ChangeExtension(first,"wav")),"Reproduced cue-10 failure on 21-cue SRT identifies exact block and publishes no partial master");Check(jobs[1].State==JobState.Done&&File.Exists(jobs[1].OutputPath)&&Starts().Length==2,"Same batch continues next file with a clean model worker");Check(jobs[0].Cues.Count==21&&Scripts.ToSrt(jobs[0].Cues)==File.ReadAllText(first),"Failed batch retains original script and locked timeline");}
  Check(ExternalSpeech.GenerationTimeoutMilliseconds("One short sentence.",true)>ExternalSpeech.GenerationTimeoutMilliseconds("One short sentence.",false),"CPU and GPU use separate finite generation budgets");
  // Identify the fixture by its unique command-line path. PID numbers alone are
  // unsafe under PID reuse and runtimes exposing different process namespaces.
  bool survivors=false;string worker=Path.Combine(ai,"worker.py");
  if(Directory.Exists("/proc")){foreach(string directory in Directory.GetDirectories("/proc")){try{string[] command=File.ReadAllText(Path.Combine(directory,"cmdline")).Split('\0');if(command.Contains(worker)){survivors=true;Console.WriteLine("SURVIVOR fixture "+Path.GetFileName(directory));}}catch(IOException){}catch(UnauthorizedAccessException){}}}
  else{foreach(string line in File.ReadAllLines(Path.Combine(ai,"allpids.txt"))){try{using(var p=Process.GetProcessById(int.Parse(line)))if(!p.HasExited&&p.ProcessName.StartsWith("python",StringComparison.OrdinalIgnoreCase)){survivors=true;Console.WriteLine("SURVIVOR fixture "+line);}}catch(ArgumentException){}}}
  Check(!survivors,"No worker subprocess survives failure, timeout, cancellation or final engine disposal");
  Console.WriteLine("TOTAL EXTERNAL CLONE "+count+" passed.");
 }
}
